class Stack<T> {
    data: T[];
    size: number;
    constructor(capacity: number) {
        this.data = new Array<T>(capacity);
        this.size = 0;
    }

    push (item: T): void {
        this.data.push(item);
        this.size++;
    }

    pop (): T {
        this.size--;
        return this.data.pop() as T;
    }

    printStack(): void {
        console.log(this.data);
    }
}

// 定义了一个存储 number 类型数据的栈 容量为10
let stack = new Stack<number>(10); 

stack.push(10);
stack.push(5);

stack.printStack(); // [ <10 empty items>, 10, 5 ]
